//VERSION=3
function setup() {
  return {
    input: ["HH", "dataMask"],
    output: [
      { id: "default", bands: 4 },
      { id: "browserStats", bands: 1 },
      { id: "dataMask", bands: 1 },
    ],
  }
}

function evaluatePixel(samples) {
  const value = Math.max(0, Math.log(samples.HH) * 0.21714724095 + 1)
  return {
    default: [value, value, value, samples.dataMask],
    browserStats: [Math.max(-30, (10 * Math.log10(samples.HH)))],
    dataMask: [samples.dataMask],
  };
}

// ---
/*
// displays HH in decibels from -20 to 0
// the following is simplified below
// var log = 10 * Math.log(HH) / Math.LN10;
// var val = Math.max(0, (log + 20) / 20);

return [Math.max(0, Math.log(HH) * 0.21714724095 + 1)];
*/

//VERSION=3
function setup() {
  return {
    input: ["HH", "dataMask"],
    output: [
      { id: "default", bands: 4 },
      { id: "browserStats", bands: 1 },
      { id: "dataMask", bands: 1 },
    ],
  }
}

function evaluatePixel(samples) {
  return {
    default: [2 * samples.HH, 2 * samples.HH, 2 * samples.HH, samples.dataMask],
    browserStats: [samples.HH],
    dataMask: [samples.dataMask],
  };
}

//VERSION=3
function setup() {
  return {
    input: ["HH", "HV", "dataMask"],
    output: { bands: 4 }
  };
}

function evaluatePixel(sample) {
  return [sample.HH / 0.28,
          sample.HV / 0.06,
          sample.HV / sample.HH / 0.49,
          sample.dataMask];
}

//VERSION=3
function setup() {
  return {
    input: ["HH", "HV", "dataMask"],
    output: { bands: 4 }
  }
}

function evaluatePixel(sample) {
  return [5.5 * sample.HV > 0.5, sample.HH, sample.HV * 8, sample.dataMask]
}

// ---

/*URBAN AREAS
  Sentinel1-AWS-IW-VVVH
*/

//return [5.5 * HV > 0.5, HH, HV * 8];

//VERSION=3
function setup() {
  return {
    input: ["HH", "HV", "dataMask"],
    output: { bands: 4 }
  }
}

function evaluatePixel(sample) {
  var water_threshold = 25; //lower means more water

  if (sample.HH / sample.HV > water_threshold) {
    // watervis
    return [sample.HH, 8 * sample.HH, 0.5 + 3 * sample.HH + 2000 * sample.HV, sample.dataMask];
  } else {
    // landvis
    return [3 * sample.HH, 1.1 * sample.HH + 8.75 * sample.HV, 1.75 * sample.HV, sample.dataMask];
  }
}

// ---

